      <g class="w-boing"><ellipse cx="110" cy="62" rx="104" ry="24" fill="#2563eb" stroke="${INK}" stroke-width="5"/><ellipse cx="110" cy="62" rx="84" ry="16" fill="#1e293b" stroke="${INK}" stroke-width="3"/></g>
