      <g class="w-glow"><circle cx="100" cy="100" r="84" fill="none" stroke="#22d3ee" stroke-width="12" opacity=".9"/><circle cx="100" cy="100" r="72" fill="url(#g${u})" stroke="${INK}" stroke-width="5"/></g>
